import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Container for the node
  const root = new Group();

  // ---------- Textured Plane ----------
  const planeGeom = new PlaneGeometry(7, 6);
  const planeMat = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
    depthWrite: true,
  });
  const plane = new Mesh(planeGeom, planeMat);
  // plane is placed at the spec‑defined Z depth
  plane.position.set(0, 0, -2.5);
  root.add(plane);

  // Load texture (if any) – async but setup is sync
  const cleanupResources = {
    textures: [],
    texts: [],
    primitives: [],
    timelines: [],
  };

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
      cleanupResources.textures.push(tex);
    });
  }

  // ---------- Text Content ----------
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  const defaultColor =
    config.intent?.visualSpec?.colors?.paper ?? '#e8ecf2';

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 31,
      color: defaultColor,
      align: 'left',
    });
    // Position text slightly in front of the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    cleanupResources.texts.push(txt);
  }

  // ---------- Event Handlers ----------
  root.userData.handlers = {};

  // ---------- Cleanup ----------
  root.userData.cleanup = () => {
    // Dispose geometry & material
    planeGeom.dispose();
    planeMat.dispose();

    // Dispose loaded textures
    cleanupResources.textures.forEach((t) => {
      if (t.dispose) t.dispose();
    });

    // Dispose any primitives (none in this spec)
    cleanupResources.primitives.forEach((p) => {
      if (p.cleanup) p.cleanup();
    });

    // Kill GSAP timelines
    cleanupResources.timelines.forEach((tl) => {
      tl.kill();
    });

    // Remove references
    root.clear();
  };

  return root;
}
